ALTER TABLE public.items ADD COLUMN IF NOT EXISTS facets_status text NOT NULL DEFAULT 'none' CHECK (facets_status IN ('none','rules','ai'));
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS georgian_preference text NOT NULL DEFAULT 'balanced' CHECK (georgian_preference IN ('less','balanced','more')), ADD COLUMN IF NOT EXISTS swipe_no integer NOT NULL DEFAULT 0;
GRANT UPDATE (georgian_preference) ON public.profiles TO authenticated;
CREATE TABLE public.item_facets(item_id uuid NOT NULL REFERENCES public.items(id) ON DELETE CASCADE,facet text NOT NULL,value text NOT NULL,confidence real NOT NULL DEFAULT 1 CHECK(confidence BETWEEN 0 AND 1),source text NOT NULL CHECK(source IN ('rule','keyword','ai','admin')),PRIMARY KEY(item_id,facet,value));
GRANT SELECT ON public.item_facets TO anon,authenticated; GRANT ALL ON public.item_facets TO service_role; GRANT INSERT,UPDATE,DELETE ON public.item_facets TO authenticated;
ALTER TABLE public.item_facets ENABLE ROW LEVEL SECURITY;
CREATE POLICY facets_read ON public.item_facets FOR SELECT USING(true);
CREATE POLICY facets_admin ON public.item_facets FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX item_facets_value_idx ON public.item_facets(facet,value);
CREATE TABLE public.user_facet_stats(user_id uuid NOT NULL,media_type text NOT NULL,facet text NOT NULL,value text NOT NULL,exposures_ew double precision NOT NULL DEFAULT 0,likes_ew double precision NOT NULL DEFAULT 0,passes_ew double precision NOT NULL DEFAULT 0,strong_ew double precision NOT NULL DEFAULT 0,last_swipe_no integer NOT NULL DEFAULT 0,PRIMARY KEY(user_id,media_type,facet,value));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.user_facet_stats TO authenticated; GRANT ALL ON public.user_facet_stats TO service_role; ALTER TABLE public.user_facet_stats ENABLE ROW LEVEL SECURITY; CREATE POLICY own_facet_stats ON public.user_facet_stats FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.user_taste(user_id uuid NOT NULL,media_type text NOT NULL,facet text NOT NULL,value text NOT NULL,stance text NOT NULL,confidence_level text NOT NULL,importance real NOT NULL DEFAULT 0,defining boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,media_type,facet,value));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.user_taste TO authenticated; GRANT ALL ON public.user_taste TO service_role; ALTER TABLE public.user_taste ENABLE ROW LEVEL SECURITY; CREATE POLICY own_taste ON public.user_taste FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.user_taste_overrides(user_id uuid NOT NULL,facet text NOT NULL,value text NOT NULL,stance text NOT NULL CHECK(stance IN ('love','avoid')),PRIMARY KEY(user_id,facet,value));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.user_taste_overrides TO authenticated; GRANT ALL ON public.user_taste_overrides TO service_role; ALTER TABLE public.user_taste_overrides ENABLE ROW LEVEL SECURITY; CREATE POLICY own_overrides ON public.user_taste_overrides FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.user_taste_portrait(user_id uuid PRIMARY KEY,archetype text NOT NULL,summary text NOT NULL,source text NOT NULL DEFAULT 'rules' CHECK(source IN ('rules','ai')),swipe_no integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.user_taste_portrait TO authenticated; GRANT ALL ON public.user_taste_portrait TO service_role; ALTER TABLE public.user_taste_portrait ENABLE ROW LEVEL SECURITY; CREATE POLICY own_portrait ON public.user_taste_portrait FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.swipe_receipts(user_id uuid NOT NULL,item_id uuid NOT NULL REFERENCES public.items(id),swipe_no integer NOT NULL,previous_no integer NOT NULL,before_stats jsonb NOT NULL,before_tags jsonb NOT NULL,dwell_ms integer NOT NULL DEFAULT 0,opened_details boolean NOT NULL DEFAULT false,PRIMARY KEY(user_id,item_id));
GRANT SELECT ON public.swipe_receipts TO authenticated; GRANT ALL ON public.swipe_receipts TO service_role; ALTER TABLE public.swipe_receipts ENABLE ROW LEVEL SECURITY; CREATE POLICY own_receipts ON public.swipe_receipts FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE INDEX IF NOT EXISTS swipes_user_time_idx ON public.swipes(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS logs_user_status_idx ON public.logs(user_id,status);
CREATE INDEX IF NOT EXISTS items_media_geo_popularity_idx ON public.items(media_type,is_georgian,popularity DESC);
CREATE OR REPLACE FUNCTION public.record_swipe(item_id uuid,action text,dwell_ms integer DEFAULT 0,opened_details boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE uid uuid:=auth.uid(); it public.items; n integer; prev integer; signal double precision; tags text[];
BEGIN
IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
IF action NOT IN ('like','pass') THEN RAISE EXCEPTION 'Invalid action'; END IF;
SELECT swipe_no INTO prev FROM profiles WHERE id=uid FOR UPDATE;
IF EXISTS(SELECT 1 FROM swipes s WHERE s.user_id=uid AND s.item_id=record_swipe.item_id) THEN RETURN false; END IF;
SELECT * INTO STRICT it FROM items WHERE id=record_swipe.item_id;
n:=prev+1; signal:=CASE WHEN n<=15 THEN 1.5 ELSE 1 END * CASE WHEN action='like' AND dwell_ms>3000 THEN 1.1 WHEN action='pass' AND opened_details THEN 0.5 WHEN action='pass' AND dwell_ms<800 THEN 0.5 ELSE 1 END;
tags:=ARRAY(SELECT DISTINCT lower(t) FROM unnest(it.genres||it.mood_tags||it.keywords) t WHERE t<>'')||ARRAY['creator:'||it.creator];
INSERT INTO swipe_receipts(user_id,item_id,swipe_no,previous_no,before_stats,before_tags,dwell_ms,opened_details)
VALUES(uid,record_swipe.item_id,n,prev,coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM user_facet_stats s WHERE s.user_id=uid AND s.media_type=it.media_type AND EXISTS(SELECT 1 FROM item_facets f WHERE f.item_id=it.id AND f.facet=s.facet AND f.value=s.value)),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM tag_weights t WHERE t.user_id=uid AND t.tag=ANY(tags)),'[]'),greatest(0,dwell_ms),opened_details);
INSERT INTO swipes(user_id,item_id,action) VALUES(uid,record_swipe.item_id,record_swipe.action);
UPDATE profiles SET swipe_no=n WHERE id=uid;
INSERT INTO user_facet_stats(user_id,media_type,facet,value,exposures_ew,likes_ew,passes_ew,last_swipe_no)
SELECT uid,it.media_type,f.facet,f.value,signal,CASE WHEN action='like' THEN signal ELSE 0 END,CASE WHEN action='pass' THEN signal ELSE 0 END,n FROM item_facets f WHERE f.item_id=it.id
ON CONFLICT(user_id,media_type,facet,value) DO UPDATE SET exposures_ew=user_facet_stats.exposures_ew*power(0.5,(n-user_facet_stats.last_swipe_no)/40.0)+EXCLUDED.exposures_ew,likes_ew=user_facet_stats.likes_ew*power(0.5,(n-user_facet_stats.last_swipe_no)/40.0)+EXCLUDED.likes_ew,passes_ew=user_facet_stats.passes_ew*power(0.5,(n-user_facet_stats.last_swipe_no)/40.0)+EXCLUDED.passes_ew,strong_ew=user_facet_stats.strong_ew*power(0.5,(n-user_facet_stats.last_swipe_no)/40.0),last_swipe_no=n;
INSERT INTO tag_weights(user_id,tag,weight) SELECT uid,t,CASE WHEN action='like' THEN 3 ELSE -2 END*signal FROM unnest(tags) t ON CONFLICT(user_id,tag) DO UPDATE SET weight=tag_weights.weight+EXCLUDED.weight,updated_at=now();
RETURN true; END $$;
REVOKE ALL ON FUNCTION public.record_swipe(uuid,text,integer,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_swipe(uuid,text,integer,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.undo_record_swipe(item_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE uid uuid:=auth.uid(); r swipe_receipts; it items;
BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
PERFORM 1 FROM profiles WHERE id=uid FOR UPDATE;
SELECT * INTO r FROM swipe_receipts s WHERE s.user_id=uid AND s.item_id=undo_record_swipe.item_id;
IF NOT FOUND THEN RETURN public.taste_action(item_id,'undo','{}','{"LIKE_DELTA":3,"PASS_DELTA":-2,"DECAY":0.97}'); END IF;
IF EXISTS(SELECT 1 FROM swipe_receipts s WHERE s.user_id=uid AND s.swipe_no>r.swipe_no) THEN RAISE EXCEPTION 'Undo the latest swipe first'; END IF;
SELECT * INTO it FROM items WHERE id=item_id;
DELETE FROM user_facet_stats s WHERE s.user_id=uid AND s.media_type=it.media_type AND EXISTS(SELECT 1 FROM item_facets f WHERE f.item_id=it.id AND f.facet=s.facet AND f.value=s.value);
INSERT INTO user_facet_stats SELECT * FROM jsonb_populate_recordset(NULL::user_facet_stats,r.before_stats);
DELETE FROM tag_weights t WHERE t.user_id=uid AND t.tag=ANY(ARRAY(SELECT DISTINCT lower(v) FROM unnest(it.genres||it.mood_tags||it.keywords) v)||ARRAY['creator:'||it.creator]);
INSERT INTO tag_weights SELECT * FROM jsonb_populate_recordset(NULL::tag_weights,r.before_tags);
DELETE FROM swipes s WHERE s.user_id=uid AND s.item_id=undo_record_swipe.item_id;
DELETE FROM swipe_receipts s WHERE s.user_id=uid AND s.item_id=undo_record_swipe.item_id;
UPDATE profiles SET swipe_no=r.previous_no WHERE id=uid; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.undo_record_swipe(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.undo_record_swipe(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.refresh_taste(user_id uuid DEFAULT auth.uid()) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE n integer; top_values text; away text;
BEGIN IF auth.uid() IS NULL OR user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Not allowed'; END IF;
SELECT swipe_no INTO n FROM profiles WHERE id=user_id;
DELETE FROM user_taste t WHERE t.user_id=refresh_taste.user_id;
INSERT INTO user_taste(user_id,media_type,facet,value,stance,confidence_level,importance,defining)
WITH decayed AS (SELECT s.*,s.exposures_ew*power(0.5,(n-last_swipe_no)/40.0) e,(s.likes_ew+0.5*s.strong_ew)*power(0.5,(n-last_swipe_no)/40.0) l FROM user_facet_stats s WHERE s.user_id=refresh_taste.user_id),base AS (SELECT media_type,least(1.0,sum(l)/greatest(1,sum(e))) b FROM decayed WHERE facet='genre' GROUP BY media_type),rates AS (SELECT d.*,coalesce(b.b,0.5) baseline,least(1.0,(l+4*coalesce(b.b,0.5))/(e+4)) rate FROM decayed d LEFT JOIN base b USING(media_type)),spread AS (SELECT media_type,facet,greatest(0.05,(max(rate)-min(rate))*least(1,sum(e)/10)) importance FROM rates GROUP BY media_type,facet)
SELECT refresh_taste.user_id,r.media_type,r.facet,r.value,CASE WHEN o.stance='love' THEN 'loves' WHEN o.stance='avoid' THEN 'avoids' WHEN e<3 THEN 'exploring' WHEN rate-baseline>=0.2 THEN 'loves' WHEN rate-baseline>=0.06 THEN 'leans_toward' WHEN rate-baseline<=-0.2 THEN 'avoids' WHEN rate-baseline<=-0.06 THEN 'leans_away' ELSE 'neutral' END,CASE WHEN e<3 THEN 'exploring' WHEN e<6 THEN 'emerging' WHEN e<15 THEN 'established' ELSE 'strong' END,s.importance,(rate>baseline+0.06 AND (SELECT count(DISTINCT g) FROM swipes sw JOIN items i ON i.id=sw.item_id JOIN item_facets f ON f.item_id=i.id CROSS JOIN LATERAL unnest(i.genres) g WHERE sw.user_id=refresh_taste.user_id AND sw.action='like' AND f.facet=r.facet AND f.value=r.value AND i.media_type=r.media_type)>=3) FROM rates r JOIN spread s USING(media_type,facet) LEFT JOIN user_taste_overrides o ON o.user_id=refresh_taste.user_id AND o.facet=r.facet AND o.value=r.value;
SELECT string_agg(replace(value,'_',' '),', ') INTO top_values FROM (SELECT DISTINCT value FROM user_taste t WHERE t.user_id=refresh_taste.user_id AND t.defining ORDER BY value LIMIT 3) q;
SELECT string_agg(replace(value,'_',' '),', ') INTO away FROM (SELECT DISTINCT value FROM user_taste t WHERE t.user_id=refresh_taste.user_id AND t.stance IN ('avoids','leans_away') ORDER BY value LIMIT 2) q;
INSERT INTO user_taste_portrait(user_id,archetype,summary,swipe_no) VALUES(refresh_taste.user_id,CASE WHEN top_values IS NULL THEN 'The Curious Explorer' ELSE 'The '||initcap(top_values)||' Explorer' END,CASE WHEN top_values IS NULL THEN 'Your taste is still taking shape. Each choice helps reveal what matters to you.' ELSE 'You keep coming back to '||top_values||'.'||CASE WHEN away IS NOT NULL THEN ' You lean away from '||away||'.' ELSE '' END END,n) ON CONFLICT(user_id) DO UPDATE SET archetype=EXCLUDED.archetype,summary=EXCLUDED.summary,swipe_no=n,updated_at=now();
END $$;
REVOKE ALL ON FUNCTION public.refresh_taste(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.refresh_taste(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_discover_queue(media_type text DEFAULT 'film',filters jsonb DEFAULT '{}',exclude_ids uuid[] DEFAULT '{}',seed text DEFAULT '',"limit" integer DEFAULT 8) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$
DECLARE uid uuid:=auth.uid(); result jsonb;
BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF;
WITH candidates AS MATERIALIZED (SELECT i.* FROM items i JOIN profiles p ON p.id=uid WHERE i.media_type=get_discover_queue.media_type AND (NOT coalesce((filters->>'georgian_only')::boolean,false) OR i.is_georgian) AND NOT i.id=ANY(exclude_ids) AND NOT i.genres && p.avoided_genres AND NOT EXISTS(SELECT 1 FROM swipes s WHERE s.user_id=uid AND s.item_id=i.id) AND NOT EXISTS(SELECT 1 FROM logs l WHERE l.user_id=uid AND l.item_id=i.id AND l.status='seen') AND NOT EXISTS(SELECT 1 FROM item_facets f JOIN user_taste_overrides o ON o.facet=f.facet AND o.value=f.value AND o.user_id=uid AND o.stance='avoid' WHERE f.item_id=i.id) AND (NOT filters ? 'facet' OR EXISTS(SELECT 1 FROM item_facets f WHERE f.item_id=i.id AND f.facet=filters->>'facet' AND f.value=filters->>'value')) AND (NOT filters ? 'tag' OR filters->>'tag'=ANY(i.genres||i.mood_tags||i.keywords||ARRAY['creator:'||i.creator])) ORDER BY CASE WHEN p.swipe_no=0 THEN coalesce(i.popularity,0) END DESC NULLS LAST,md5(i.id::text||seed) LIMIT 300),scored AS (SELECT c.*,coalesce(m.score,0)+coalesce(t.weight,0)*0.02+((('x'||substr(md5(c.id::text||seed),1,6))::bit(24)::int)/16777215.0)*0.05 AS score,m.matches FROM candidates c LEFT JOIN tag_weights t ON t.user_id=uid AND t.tag='creator:'||c.creator LEFT JOIN LATERAL (SELECT sum(v.contribution) score,array_agg(v.value ORDER BY v.contribution DESC) FILTER(WHERE v.contribution>0) matches FROM (SELECT f.value,f.confidence*coalesce(ut.importance,0.1)*CASE WHEN o.stance='love' THEN 1 WHEN ut.stance='loves' THEN 1 WHEN ut.stance='leans_toward' THEN 0.5 WHEN ut.stance='leans_away' THEN -0.5 WHEN ut.stance='avoids' THEN -1 ELSE 0 END*CASE WHEN ut.confidence_level='strong' THEN 1 WHEN ut.confidence_level='established' THEN 0.8 ELSE 0.5 END contribution FROM item_facets f LEFT JOIN user_taste ut ON ut.user_id=uid AND ut.media_type=c.media_type AND ut.facet=f.facet AND ut.value=f.value LEFT JOIN user_taste_overrides o ON o.user_id=uid AND o.facet=f.facet AND o.value=f.value WHERE f.item_id=c.id UNION ALL SELECT tag,least(0.2,greatest(-0.2,weight/25.0)) FROM tag_weights WHERE user_id=uid AND tag=ANY(c.genres||c.mood_tags||c.keywords) AND NOT EXISTS(SELECT 1 FROM item_facets f WHERE f.item_id=c.id)) v) m ON true),ranked AS (SELECT s.*,row_number() OVER(PARTITION BY is_georgian ORDER BY score DESC) group_no FROM scored s),ordered AS (SELECT r.*,CASE WHEN is_georgian THEN group_no*(CASE p.georgian_preference WHEN 'less' THEN 12 WHEN 'more' THEN 3 ELSE 6 END) ELSE group_no+floor((group_no-1)::numeric/(CASE p.georgian_preference WHEN 'less' THEN 11 WHEN 'more' THEN 2 ELSE 5 END)) END slot FROM ranked r JOIN profiles p ON p.id=uid),picked AS (SELECT * FROM ordered ORDER BY CASE WHEN coalesce((filters->>'georgian_only')::boolean,false) THEN group_no ELSE slot END,score DESC LIMIT greatest(1,least(8,get_discover_queue."limit")))
SELECT coalesce(jsonb_agg(jsonb_build_object('item',jsonb_build_object('id',id,'media_type',picked.media_type,'title_en',title_en,'title_ka',title_ka,'creator',creator,'year',year,'genres',genres,'mood_tags',mood_tags,'keywords',keywords,'runtime_minutes',runtime_minutes,'page_count',page_count,'image_source',image_source,'image_ref',image_ref,'is_georgian',is_georgian,'tmdb_id',tmdb_id),'reason',CASE WHEN cardinality(matches)>0 THEN initcap(replace(array_to_string(matches[1:3],', '),'_',' '))||': traits you keep coming back to.' ELSE 'A varied starter pick.' END,'matched',coalesce(matches,'{}'),'score',score,'exploratory',false)),'[]') INTO result FROM picked;
RETURN result; END $$;
REVOKE ALL ON FUNCTION public.get_discover_queue(text,jsonb,uuid[],text,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_discover_queue(text,jsonb,uuid[],text,integer) TO authenticated;